import { encodeImageUri, forgeImageURL } from '@proton/shared/lib/helpers/image';

import { API_URL } from 'proton-mail/config';

const LinksURLs: { [key: string]: string } = {};
const ImageURLs: {
    [key: string]: {
        src: string;
        'proton-src'?: string;
        class?: string;
        id?: string;
        'data-embedded-img'?: string;
    };
} = {};
export const ASSISTANT_IMAGE_PREFIX = '#'; // Prefix to generate unique IDs
let indexURL = 0; // Incremental index to generate unique IDs

// Replace URLs by a unique ID and store the original URL
export const replaceURLs = (dom: Document, uid: string): Document => {
    // Find all links in the DOM
    const links = dom.querySelectorAll('a[href]');

    // Replace URLs in links
    links.forEach((link) => {
        const hrefValue = link.getAttribute('href') || '';
        if (hrefValue) {
            const key = `${ASSISTANT_IMAGE_PREFIX}${indexURL++}`;
            LinksURLs[key] = hrefValue;
            link.setAttribute('href', key);
        }
    });

    /**
     * We also want to search for images, however we need to put additional logic here.
     * #### REMOTE IMAGE ####
     * Since often proxy images to avoid IP leak from the user, we have multiple cases:
     * 1- Image has a "src" attribute only
     *          => User added a remote image in the composer, OR do not have the setting load images with proxy
     * 2- Image has a "proton-src" attribute only
     *          => This happens when opening an old draft (when setting is set to load with proxy).
     *          The "real" image url in src attribute is prefixed with "proton", so that it does not get loaded,
     *          which could leak user IP. So in that case, the image is not loaded, but still present in the DOM.
     *          When sending, we will remove the attribute on the fly, so the image will be sent.
     *          This behaviour needs to be improved in the future.
     * 3- Image has both "proton-src" and "src" attributes
     *          => This happens when you reply to a message that had images loaded.
     *          Basically, the image is shown in the composer using the proxy url, and we will replace it with the true url
     *          on the fly before sending.
     *
     *
     * The goal to keep images properly formatted with a refine is to keep as much information as possible (src, proton-src, class)
     * Also, we would like to load images that are not loaded when clicking on refine,
     * otherwise we would get broken images in the generation, which is something we would like to avoid.
     *
     * To do so, here is what we are doing:
     * 1- We search for all images with src attributes
     *      a- If image also has proton-src attribute, then we can add src, proton-src (and class if any) to our "ImageURLs" object
     *      b- If image has no proton-src, it's already loaded, so we can store it directly without additional manipulation
     * 2- We search for images wit proton-src attributes.
     *      - If image also has a src attribute, then we already made what was needed in 1.a.
     *      - If no src attribute, then the image is not loaded. What we do is the following:
     *          - We store proton-src
     *          - We proxy this url and store it in src, so that we'll be able to load the image without leaking user IP.
     *
     *
     * #### EMBEDDED IMAGE ####
     * Embedded images are also identified by a "data-embedded-img" and "id" attribute.
     * So during the previous check, we are also storing these values
     */
    const images = dom.querySelectorAll('img[src]');
    const protonSrcImages = dom.querySelectorAll('img[proton-src]');

    images.forEach((image) => {
        const srcValue = image.getAttribute('src');
        const protonSrcValue = image.getAttribute('proton-src');
        const classValue = image.getAttribute('class');
        const dataValue = image.getAttribute('data-embedded-img');
        const idValue = image.getAttribute('id');

        const commonAttributes = {
            class: classValue ? classValue : undefined,
            'data-embedded-img': dataValue ? dataValue : undefined,
            id: idValue ? idValue : undefined,
        };
        if (srcValue && protonSrcValue) {
            const key = `${ASSISTANT_IMAGE_PREFIX}${indexURL++}`;
            ImageURLs[key] = {
                src: srcValue,
                'proton-src': protonSrcValue,
                ...commonAttributes,
            };
            image.setAttribute('src', key);
        } else if (srcValue) {
            const key = `${ASSISTANT_IMAGE_PREFIX}${indexURL++}`;
            ImageURLs[key] = {
                src: srcValue,
                ...commonAttributes,
            };
            image.setAttribute('src', key);
        }
    });

    protonSrcImages.forEach((image) => {
        const srcValue = image.getAttribute('src');
        const protonSrcValue = image.getAttribute('proton-src');
        const classValue = image.getAttribute('class');
        const dataValue = image.getAttribute('data-embedded-img');
        const idValue = image.getAttribute('id');
        if (srcValue && protonSrcValue) {
            return;
        } else if (protonSrcValue) {
            const key = `${ASSISTANT_IMAGE_PREFIX}${indexURL++}`;
            const encodedImageUrl = encodeImageUri(protonSrcValue);
            const proxyImage = forgeImageURL({
                apiUrl: API_URL,
                url: encodedImageUrl,
                uid,
                origin: window.location.origin,
            });

            ImageURLs[key] = {
                src: proxyImage,
                'proton-src': protonSrcValue,
                class: classValue ? classValue : undefined,
                'data-embedded-img': dataValue ? dataValue : undefined,
                id: idValue ? idValue : undefined,
            };
            image.setAttribute('src', key);
        }
    });

    return dom;
};

// Restore URLs (in links and images) from unique IDs
export const restoreURLs = (dom: Document): Document => {
    // Find all links and image in the DOM
    const links = dom.querySelectorAll('a[href]');
    const images = dom.querySelectorAll('img[src]');

    // Restore URLs in links
    links.forEach((link) => {
        const hrefValue = link.getAttribute('href') || '';
        if (hrefValue && LinksURLs[hrefValue]) {
            link.setAttribute('href', LinksURLs[hrefValue]);
        }
    });

    // Restore URLs in images
    images.forEach((image) => {
        const srcValue = image.getAttribute('src') || '';
        if (srcValue && ImageURLs[srcValue]) {
            image.setAttribute('src', ImageURLs[srcValue].src);
            if (ImageURLs[srcValue]['proton-src']) {
                image.setAttribute('proton-src', ImageURLs[srcValue]['proton-src']);
            }
            if (ImageURLs[srcValue].class) {
                image.setAttribute('class', ImageURLs[srcValue].class);
            }
            if (ImageURLs[srcValue]['data-embedded-img']) {
                image.setAttribute('data-embedded-img', ImageURLs[srcValue]['data-embedded-img']);
            }
            if (ImageURLs[srcValue].id) {
                image.setAttribute('id', ImageURLs[srcValue].id);
            }
        }
    });

    return dom;
};

import markdownit from 'markdown-it';

import { defaultFontStyle } from '@proton/components/components/editor/helpers';
import type { MailSettings, UserSettings } from '@proton/shared/lib/interfaces';

import { templateBuilder } from './message/messageSignature';
import { toText } from './parserHtml';

export const SIGNATURE_PLACEHOLDER = '--protonSignature--';

const OPTIONS = {
    breaks: true,
    linkify: true,
};

const md = markdownit('default', OPTIONS).disable(['lheading', 'heading', 'list', 'code', 'fence', 'hr']);

/**
 * This function generates a random string that is not included in the input text.
 * This is used to be able to insert and remove placeholders in new lines, so markdown will treat those newlines
 * as not empty. Therefore we need the placeholders to be unique, to not remove parts of the text when we
 * remove the placeholders.
 *
 * To ensure the placeholder is unique we try a random string, which should be with > 99% chance unique,
 * but if it's not unique, we'll retry to make the function always behave correctly.
 * @param text
 * @returns {string}
 */
const generatePlaceHolder = (text: string) => {
    let placeholder = '';
    do {
        placeholder = Math.random().toString(36).substring(3) + Math.random().toString(36).substring(3);
    } while (text.includes(placeholder));
    return placeholder;
};

/**
 * Fills a given text with newlines with placeholders that can be removed later.
 * For instance the following input:
 * "
 *
 *
 * "
 * is turned into
 * "
 * placeholder
 * "
 * The input is not turned into
 * "placeholder
 * placeholder
 * placeholder"
 * as we expect the first new line to come from an non empty new line, and the last new line is followed by a non
 * empty new line. This is how addNewLinePlaceholders uses this function.
 */
const newLineIntoPlaceholder = (match: string, placeholder: string) =>
    match.replace(/(\r\n|\n)/g, (match) => match + placeholder).replace(new RegExp(`${placeholder}$`, 'g'), '');

/**
 * Turns any empty lines into lines filled with the specified placeholder
 * to trick the markdown converter into keeping
 * those empty lines.
 */
const addNewLinePlaceholders = (text: string, placeholder: string) => {
    const startingNewline = text.startsWith('\n') ? text : `\n${text}`;
    const textWPlaceholder = startingNewline.replace(/((\r\n|\n)\s*(\r\n|\n))+/g, (match) =>
        newLineIntoPlaceholder(match, placeholder)
    );
    // don't remove empty new lines before '>'
    const noEmptyLines = textWPlaceholder.replace(/^\n/g, '');

    // add an empty line (otherwise markdownit doesnt end the blockquote) if it comes after a `>`
    return noEmptyLines.replace(/(>[^\r\n]*(?:\r\n|\n))(\s*[^>])/g, (match, line1, line2) => `${line1}\n${line2}`);
};

const removeNewLinePlaceholder = (html: string, placeholder: string) => html.replace(new RegExp(placeholder, 'g'), '');

/**
 * Escapes backslashes from the input text with another backslash.
 */
const escapeBackslash = (text = '') => text.replace(/\\/g, '\\\\');

export const prepareConversionToHTML = (content: string) => {
    // We want empty new lines to behave as if they were not empty (this is non-standard markdown behaviour)
    // It's more logical though for users that don't know about markdown.
    const placeholder = generatePlaceHolder(content);
    // We don't want to treat backslash as a markdown escape since it removes backslashes. So escape all backslashes with a backslash.
    const withPlaceholder = addNewLinePlaceholders(escapeBackslash(content), placeholder);
    const rendered = md.render(withPlaceholder);
    return removeNewLinePlaceholder(rendered, placeholder);
};

export const extractContentFromPtag = (content: string) => {
    return /^<p>(((?!<p>)[\s\S])*)<\/p>$/.exec(content)?.[1];
};

/**
 * Replace the signature by a temp hash, we replace it only
 * if the content is the same.
 */
const replaceSignature = (
    input: string,
    signature: string,
    mailSettings: MailSettings | undefined,
    userSettings: UserSettings | undefined
) => {
    const fontStyle = defaultFontStyle(mailSettings);
    const signatureTemplate = templateBuilder(signature, mailSettings, userSettings, fontStyle, false, true);
    const signatureText = toText(signatureTemplate)
        .replace(/\u200B/g, '')
        .trim();

    return input.replace(signatureText, SIGNATURE_PLACEHOLDER);
};

/**
 * Replace the hash by the signature inside the message formated as HTML
 * We prevent too many lines to be added as we already have a correct message
 */
const attachSignature = (
    input: string,
    signature: string,
    plaintext: string,
    mailSettings: MailSettings | undefined,
    userSettings: UserSettings | undefined
) => {
    const fontStyle = defaultFontStyle(mailSettings);
    const signatureTemplate = templateBuilder(
        signature,
        mailSettings,
        userSettings,
        fontStyle,
        false,
        !plaintext.startsWith(SIGNATURE_PLACEHOLDER)
    );
    return input.replace(SIGNATURE_PLACEHOLDER, signatureTemplate);
};

export const textToHtml = (
    input = '',
    signature: string,
    mailSettings: MailSettings | undefined,
    userSettings: UserSettings | undefined
) => {
    const text = replaceSignature(input, signature, mailSettings, userSettings);

    const html = prepareConversionToHTML(text);

    const withSignature = attachSignature(html, signature, text, mailSettings, userSettings).trim();

    /**
     * The capturing group includes negative lookup "(?!<p>)" in order to avoid nested problems.
     * Ex, this capture will be ignored : "<p>Hello</p><p>Hello again</p>""
     * Because it would have ended up with this result : "Hello</p><p>Hello again"
     */
    return extractContentFromPtag(withSignature) || withSignature;
};
